<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { ArrowRight, CalendarDays, ChartNoAxesCombined, Database, ShieldCheck, Trophy } from 'lucide-vue-next'
import { motion } from 'motion-v'
import { useRoute } from 'vue-router'
import AnalyticsChart from '../components/charts/AnalyticsChart.vue'
import ProbabilityRing from '../components/charts/ProbabilityRing.vue'
import SportIdentity from '../components/identity/SportIdentity.vue'
import SportCrumbs from '../components/navigation/SportCrumbs.vue'
import LoadingState from '../components/ui/LoadingState.vue'
import LoadError from '../components/ui/LoadError.vue'
import { entityRoute, gamePrediction, metricValue, probability, sportLabel } from '../domain/sports'
import { sportById } from '../config/sports'
import { api } from '../services/api'
const props=defineProps({sport:{type:String,required:true}}),route=useRoute(),payload=ref(null),loading=ref(true),error=ref('')
const active=computed(()=>sportById(props.sport)),league=computed(()=>payload.value?.identity||{}),standings=computed(()=>payload.value?.standings||[])
const builderRoute=computed(()=>({path:`/${props.sport}/builder`,query:{competition:league.value.id,discipline:league.value.discipline}}))
const season=computed(()=>props.sport==='basketball'?'NBA 2025–26':new Date().getUTCFullYear())
const leagueSummary=computed(()=>{const fallback=`${league.value.name} fixtures, team form, source-backed table context and competition-specific prediction evidence.`;const text=String(league.value.description||fallback).replace(/\s+/g,' ').trim();const sentences=text.match(/[^.!?]+[.!?]+/g)||[text];const concise=sentences.slice(0,2).join(' ').trim();return concise.length>520?`${concise.slice(0,517).trim()}…`:concise})
const chart=computed(()=>{const rows=standings.value.slice(0,12);const value=row=>props.sport==='basketball'?Number(row.pct||0)*100:props.sport==='football'?Number(row.points||0):Number(row.statistics?.rating||row.points||0);return{labels:rows.map(row=>row.code||row.name),values:rows.map(value)}})
const load=async()=>{loading.value=true;error.value='';try{payload.value=await api.sportWorkspace(props.sport,'league',route.params.id,{discipline:route.query.discipline})}catch(caught){error.value=caught?.message||'The competition workspace could not be loaded.'}finally{loading.value=false}}
watch(()=>[props.sport,route.params.id],load);onMounted(load)
</script>
<template><div class="league" :style="{'--sport':active.accent}"><LoadingState v-if="loading" label="Opening competition workspace" detail="Joining fixtures, identities, standings and model evidence."/><LoadError v-else-if="error" :message="error" @retry="load"/><template v-else>
  <SportCrumbs :items="[{label:sportLabel(sport),to:active.route},{label:'Competitions',to:`${active.route}/leagues`},{label:league.name}]"/>
  <section class="league-hero"><div class="league-copy"><span class="eyebrow">{{league.group}} / {{season}}</span><div class="identity"><SportIdentity :identity="league" :size="92" square/><h1>{{league.name}}<i>.</i></h1></div><p>{{leagueSummary}}</p><nav><RouterLink :to="builderRoute">OPEN {{league.code}} BUILDER <ArrowRight/></RouterLink><RouterLink :to="{path:`${active.route}/games`,query:{competition:league.id,discipline:league.discipline}}">ALL MATCHES</RouterLink></nav></div><aside><span>COMPETITION COVERAGE</span><b>{{payload.teams.length}} teams</b><dl><div><dt>UPCOMING</dt><dd>{{payload.games.upcoming.length}}</dd></div><div><dt>RECENT</dt><dd>{{payload.games.recent.length}}</dd></div><div><dt>FORECASTS</dt><dd>{{payload.predictions.length}}</dd></div></dl><small>{{payload.source}}</small></aside></section>
  <section class="league-grid"><article class="table-panel"><header><div><span class="eyebrow">CURRENT ORDER</span><h2>{{sport==='esports'?'Power index':'Table & form'}}</h2></div><Trophy/></header><div class="standings"><RouterLink v-for="(row,index) in standings.slice(0,16)" :key="row.id" :to="entityRoute(sport,'teams',row,{competition:league.id,discipline:league.discipline})"><span>{{String(index+1).padStart(2,'0')}}</span><SportIdentity :identity="row" :size="34"/><b>{{row.name}}</b><em v-if="sport==='basketball'">{{row.wins}}–{{row.losses}}</em><em v-else-if="sport==='football'">{{row.points}} PTS</em><em v-else>{{row.statistics?.rating||row.points||'—'}}</em><i v-if="row.form?.length">{{row.form.join(' ')}}</i></RouterLink></div></article>
    <article class="chart-panel"><header><span class="eyebrow">LEAGUE SHAPE</span><h2>{{sport==='basketball'?'Win percentage':sport==='football'?'Points hierarchy':'Team rating distribution'}}</h2></header><AnalyticsChart :labels="chart.labels" :series="[{label:sport==='basketball'?'Win %':sport==='football'?'Points':'Rating',values:chart.values}]" :begin-at-zero="sport!=='esports'" :height="410"/><p>This visualization uses the current captured table—not a simulated standing.</p></article></section>
  <section class="fixture-section"><header><div><span class="eyebrow">NEXT ON THE CALENDAR</span><h2>Upcoming {{sport==='esports'?'series':'fixtures'}}</h2></div><CalendarDays/></header><div class="fixtures"><motion.article v-for="game in payload.games.upcoming.slice(0,9)" :key="game.id" :while-hover="{y:-3}"><RouterLink :to="entityRoute(sport,'games',game,{competition:league.id,discipline:league.discipline,tournament:league.id})"><small>{{game.date}} · {{game.time}} · {{game.round}}</small><div><span><SportIdentity :identity="game.away" :size="42"/><b>{{game.away?.name}}</b></span><em>VS</em><span><SportIdentity :identity="game.home" :size="42"/><b>{{game.home?.name}}</b></span></div><footer><span>{{game.venue}}</span><strong v-if="gamePrediction(game)">{{gamePrediction(game).label}} · {{probability(gamePrediction(game).probability)}}</strong><strong v-else>MODEL EVIDENCE PENDING</strong></footer></RouterLink></motion.article></div></section>
  <section class="forecast-section"><header><div><span class="eyebrow">MODEL WATCHLIST</span><h2>Strongest available signals</h2></div><ChartNoAxesCombined/></header><div v-if="payload.predictions.length" class="forecasts"><article v-for="game in payload.predictions.slice(0,4)" :key="game.id"><ProbabilityRing :value="gamePrediction(game)?.probability" :label="gamePrediction(game)?.label" :detail="`${game.away?.name} @ ${game.home?.name}`" :size="165"/><div><small>{{game.date}} · MODEL PROBABILITY</small><h3>{{gamePrediction(game)?.label}}</h3><p v-if="game.prediction?.expected_goals">Expected goals {{metricValue(game.prediction.expected_goals.home,2)}}–{{metricValue(game.prediction.expected_goals.away,2)}}. This forecast is {{game.prediction.builder_eligible?'builder eligible':'available for analysis'}}.</p><p v-else>Current evidence comes from {{game.prediction?.model}} and is {{game.prediction?.builder_eligible?'builder eligible':'available for analysis'}}.</p><RouterLink :to="entityRoute(sport,'games',game,{competition:league.id,discipline:league.discipline,tournament:league.id})">OPEN EVIDENCE <ArrowRight/></RouterLink></div></article></div><div v-else class="empty"><Database/><b>No competition forecast is attached to the current fixture IDs.</b><p>The league remains navigable, but NINTH will not invent probabilities to fill this panel.</p></div></section>
</template></div></template>
<style scoped>.league{padding:18px 0 70px}.league-hero{min-height:480px;display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:70px;align-items:center;border-bottom:1px solid var(--line)}.identity{display:flex;align-items:center;gap:24px;margin:20px 0}.identity h1{margin:0;font-size:clamp(58px,8vw,118px);line-height:.8;letter-spacing:-.085em}.identity h1 i{font-style:normal;color:var(--sport)}.league-copy>p{max-width:740px;color:var(--muted);font-size:14px;line-height:1.7}.league-copy nav{display:flex;gap:8px;margin-top:25px}.league-copy nav a{min-height:45px;padding:0 14px;display:flex;align-items:center;gap:8px;border:1px solid var(--line);color:var(--text);text-decoration:none;font:800 9px 'DM Mono'}.league-copy nav a:first-child{background:var(--contrast);color:var(--on-contrast)}.league-copy nav svg{width:15px;color:var(--sport)}.league-hero aside{min-height:310px;padding:25px;display:flex;flex-direction:column;border-top:4px solid var(--sport);background:var(--contrast);color:var(--on-contrast)}.league-hero aside>span{margin-top:auto;font:700 8px 'DM Mono';color:var(--sport)}.league-hero aside>b{margin:10px 0 22px;font-size:33px}.league-hero dl{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#343a33}.league-hero dl div{padding:10px;background:#151915}.league-hero dt{font:600 6px 'DM Mono';color:#8f978c}.league-hero dd{margin:6px 0 0;font:800 17px 'DM Mono'}.league-hero aside small{margin-top:20px;color:#8f978c;font-size:8px;line-height:1.5}.league-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:12px;margin-top:35px}.table-panel,.chart-panel,.fixture-section,.forecast-section{border:1px solid var(--line);background:var(--surface)}.table-panel>header,.chart-panel>header,.fixture-section>header,.forecast-section>header{min-height:86px;padding:17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}h2{margin:5px 0 0;font-size:27px;letter-spacing:-.05em}.table-panel header svg,.fixture-section header svg,.forecast-section header svg{color:var(--sport)}.standings a{min-height:56px;padding:8px 12px;display:grid;grid-template-columns:24px 38px 1fr auto auto;align-items:center;gap:9px;border-bottom:1px solid var(--line);text-decoration:none}.standings a>span{font:600 7px 'DM Mono';color:var(--muted)}.standings a>b{font-size:11px}.standings a>em{font:800 9px 'DM Mono';font-style:normal}.standings a>i{font:600 7px 'DM Mono';font-style:normal;color:var(--muted)}.chart-panel{padding-bottom:12px}.chart-panel>header{border:0}.chart-panel>div{padding:0 12px}.chart-panel>p{padding:0 17px;color:var(--muted);font-size:8px}.fixture-section,.forecast-section{margin-top:12px}.fixtures{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line)}.fixtures article{background:var(--surface)}.fixtures a{min-height:225px;padding:15px;display:flex;flex-direction:column;color:var(--text);text-decoration:none}.fixtures a>small{font:600 7px 'DM Mono';color:var(--muted)}.fixtures a>div{margin:auto 0;display:grid;grid-template-columns:1fr 25px 1fr;align-items:center;gap:8px}.fixtures a>div span{display:grid;justify-items:center;gap:8px;text-align:center}.fixtures a>div b{font-size:10px}.fixtures a>div>em{font:800 8px 'DM Mono';font-style:normal;color:var(--muted)}.fixtures footer{display:flex;justify-content:space-between;gap:12px;padding-top:11px;border-top:1px solid var(--line);font:600 6px 'DM Mono';color:var(--muted)}.fixtures footer strong{color:var(--sport);text-align:right}.forecasts{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.forecasts article{min-height:245px;padding:19px;display:flex;align-items:center;gap:21px;background:var(--surface)}.forecasts article>div:last-child{display:grid;gap:7px}.forecasts small{font:700 7px 'DM Mono';color:var(--sport)}.forecasts h3{margin:0;font-size:18px}.forecasts p,.empty p{margin:0;color:var(--muted);font-size:9px;line-height:1.55}.forecasts a{display:flex;align-items:center;gap:7px;color:var(--text);font:700 7px 'DM Mono';text-decoration:none}.forecasts a svg{width:13px}.empty{min-height:280px;display:grid;place-items:center;align-content:center;text-align:center;gap:10px}.empty svg{color:var(--sport)}@media(max-width:1050px){.league-hero{grid-template-columns:1fr;padding:45px 0}.league-hero aside{min-height:250px}.league-grid{grid-template-columns:1fr}.fixtures{grid-template-columns:repeat(2,1fr)}.forecasts{grid-template-columns:1fr}}@media(max-width:620px){.identity{align-items:flex-start;flex-direction:column}.league-copy nav{flex-direction:column}.league-copy nav a{justify-content:center}.fixtures{grid-template-columns:1fr}.forecasts article{align-items:flex-start;flex-direction:column}.standings a{grid-template-columns:20px 38px 1fr auto}.standings a>i{display:none}}</style>
